const app = express();

// Define variables
let favorableOutcomes; // Replace with actual count
let totalPossibleOutcomes; // Replace with actual count

const calculateProbability = () => {
    const probabilityProject = favorableOutcomes / totalPossibleOutcomes;

    return probabilityProject;
};

app.get('/', async() => {
    let result = await calculateProbability();
        res.json(result);
});
```

5. **Interpret Your Results**:
   Once you have calculated your probability using the above code snippet, you will get a decimal value representing the chance of your event happening.


