    /**
     * Calculate the probability of an event.
     *
     * @param events { number }
     * @param totalEvents { number }
     * @return double
     */
    public static double calculateProbability(int events, int totalEvents) {
        if (totalEvents == 0) {
            return 0;
        }

        double probability = (events / totalEvents);
        return probability;
    }

    /**
     * Main method.
     *
     * @param args String[]
     */
    public static void main(String[] args) {
        int events = 5; // Number of successful events
        int totalEvents = 10; // Total number of events

        double probability = calculateProbability(events, totalEvents);

        System.out.println("Probability: " + probability);
    }
}

