import java.util.*;

public class ProbabilityCalculator {

    public static double calculateProbability(int events, int totalEvents) {
        if(totalEvents == 0) {
            throw new RuntimeException("Total Events cannot be zero");
        }

        double probability = events / totalEvents;
        return probability;
    }

    public static void main(String[] args) {
        int events = 5;
        int totalEvents = 10;

        try {
            double probability = calculateProbability(events, totalEvents);
            System.out.println("Probability : "+probability);
        } catch(Exception e) {
            System.out.println(e.getMessage());
        }
    }
}
