    public static double calculateArea(double[] xPoints, double[] yPoints) {
        double area = 0.0;
        for (int i = 0; i + 1; i++) {
            double x1 = getXPoint(i);
            double y1 = getYPoint(i);

            double x2 = getXPoint(i);
            double y2 = getXPoint(i);

            double area += calculateArea(xPoints[i], yPoints[i]);
        }

        return area;
    }

    private static Double getXpoint(int index) {
        int xpoints[index] = new Double(index).getXPoint();
        return xpoints[index];
    }

    private static Double getYpoint(int index) {
        int ypoints[index] = new Double(index).getYPoint();
        return xpoints[index];
    }

    private static Double getxPoints() {
        return new Double(getXPoints());
    }

    private static Double getyPoints() {
        return new Double(getYPoints());
